import { GoogleGenAI, Type, Modality, LiveServerMessage } from "@google/genai";
import { UserPreferences, Roadmap, Project, Area, Task, Resource, DifficultyLevel } from '../types';

// Helper: Custom base64 decoding following SDK guidelines
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

// Helper: Custom base64 encoding following SDK guidelines
function encode(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

// Helper: Custom audio decoding following SDK guidelines for raw PCM streams
async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const safeParseJSON = (text: string) => {
  try {
    let clean = text.replace(/```json/gi, '').replace(/```/g, '');
    clean = clean.trim();
    return JSON.parse(clean);
  } catch (e) {
    console.error("JSON Parse Failed. Raw Text:", text);
    throw new Error("Failed to parse AI response. Please try again.");
  }
};

const getApiKey = (): string | undefined => {
  try {
    const stored = localStorage.getItem('linguasphere_profile');
    if (stored) {
      const profile = JSON.parse(stored);
      if (profile.apiKeys?.google && profile.apiKeys.google.trim() !== '') {
        return profile.apiKeys.google;
      }
    }
  } catch (e) {}
  return process.env.API_KEY;
};

const getClient = () => {
    return new GoogleGenAI({ apiKey: getApiKey() });
};

export const validateApiKey = async (apiKey: string): Promise<boolean> => {
    try {
        const ai = new GoogleGenAI({ apiKey });
        await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: "Test connection.",
        });
        return true;
    } catch (e) {
        console.error("API Key Validation Failed:", e);
        return false;
    }
};

export interface SmartAnalysisResult {
  type: string;
  difficulty: DifficultyLevel;
  tags: string[];
  skills: string[];
  notes: string;
}

export const smartAnalyzeResource = async (title: string, url: string, nativeLanguage: string): Promise<SmartAnalysisResult> => {
    const ai = getClient();
    const prompt = `
        Analyze this language learning resource using the "Low Pressure x High Challenge" framework:
        Title: ${title}
        URL: ${url}

        Logic:
        - Identify "Input" (Low Pressure) vs "Output" (High Challenge) potential.
        - If YouTube, suggest "Shadowing" techniques.
        - If text, suggest "Retelling" or "Translation" drills.

        Return JSON with:
        1. Resource Type: strictly [Music, Video, Book, Article, Podcast, Course, App].
        2. Difficulty (Easy, Medium, Hard, Extreme)
        3. Tags (up to 5 topics)
        4. Skills (Listening, Speaking, Writing, Reading, Vocabulary, Grammar, Pronunciation)
        5. Notes/Summary: Supportively summarize in ${nativeLanguage}. Highlight the "High Challenge" entry point.

        {
            "type": "...",
            "difficulty": "...",
            "tags": ["...", "..."],
            "skills": ["...", "..."],
            "notes": "..."
        }
    `;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: { responseMimeType: "application/json" }
        });
        return safeParseJSON(response.text);
    } catch (e) {
        return { type: "Video", difficulty: "Medium", tags: [], skills: [], notes: "Analysis failed." };
    }
};

