export class LiveSession {
  private sessionPromise: Promise<any> | null = null;
  private inputAudioContext: AudioContext | null = null;
  private outputAudioContext: AudioContext | null = null;
  private nextStartTime = 0;
  private sources = new Set<AudioBufferSourceNode>();
  private stream: MediaStream | null = null;

  async start(onUpdate: (status: string) => void) {
    const ai = getClient();
    this.inputAudioContext = new AudioContext({sampleRate: 16000});
    this.outputAudioContext = new AudioContext({sampleRate: 24000});
    this.stream = await navigator.mediaDevices.getUserMedia({ audio: true });

    this.sessionPromise = ai.live.connect({
      model: 'gemini-2.5-flash-native-audio-preview-12-2025',
      callbacks: {
        onopen: () => {
          onUpdate("Connected & Listening");
          if (this.inputAudioContext && this.stream) {
              const source = this.inputAudioContext.createMediaStreamSource(this.stream);
              const scriptProcessor = this.inputAudioContext.createScriptProcessor(4096, 1, 1);
              scriptProcessor.onaudioprocess = (audioProcessingEvent) => {
                const inputData = audioProcessingEvent.inputBuffer.getChannelData(0);
                const l = inputData.length;
                const int16 = new Int16Array(l);
                for (let i = 0; i < l; i++) {
                    int16[i] = inputData[i] * 32768;
                }
                const pcmBlob = {
                    data: encode(new Uint8Array(int16.buffer)),
                    mimeType: 'audio/pcm;rate=16000',
                };
                this.sessionPromise?.then((session) => {
                    session.sendRealtimeInput({ media: pcmBlob });
                });
              };
              source.connect(scriptProcessor);
              scriptProcessor.connect(this.inputAudioContext.destination);
          }
        },
        onmessage: async (message: LiveServerMessage) => {
          const base64EncodedAudioString = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (base64EncodedAudioString && this.outputAudioContext) {
            this.nextStartTime = Math.max(this.nextStartTime, this.outputAudioContext.currentTime);
            const audioBuffer = await decodeAudioData(
              decode(base64EncodedAudioString),
              this.outputAudioContext,
              24000,
              1,
            );
            const source = this.outputAudioContext.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(this.outputAudioContext.destination);
            source.addEventListener('ended', () => {
              this.sources.delete(source);
            });
            source.start(this.nextStartTime);
            this.nextStartTime += audioBuffer.duration;
            this.sources.add(source);
          }

          if (message.serverContent?.interrupted) {
            for (const source of this.sources.values()) {
              source.stop();
            }
            this.sources.clear();
            this.nextStartTime = 0;
          }
        },
        onerror: (e) => {
            console.error("Live session error:", e);
            onUpdate("Error");
        },
        onclose: () => onUpdate("Closed"),
      },
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {prebuiltVoiceConfig: {voiceName: 'Zephyr'}},
        },
        systemInstruction: 'You are a high-performance language coach. You specialize in real-time shadowing and error correction. You push the user to speak more naturally and challenge their assumptions about grammar. Keep the tone encouraging but strict on output quality.',
      }
    });
  }

  async stop() {
    if (this.sessionPromise) {
        const session = await this.sessionPromise;
        session.close();
    }
    if (this.stream) {
        this.stream.getTracks().forEach(track => track.stop());
    }
    if (this.inputAudioContext) {
        this.inputAudioContext.close();
    }
    if (this.outputAudioContext) {
        this.outputAudioContext.close();
    }
    this.sources.forEach(s => s.stop());
    this.sources.clear();
  }
}

import React, { useMemo, useState, useEffect } from 'react';
import { DailyPlan, Project, Resource, Area, Task, UserProfile, Flashcard, SUPPORTED_LANGUAGES } from '../types';
import { generateDailyMotivation } from '../services/geminiService';

interface DashboardProps {
  plans: Record<string, DailyPlan>;
  projects: Project[];
  resources: Resource[];
  areas: Area[];
  userProfile: UserProfile;
  flashcards: Flashcard[];
}

// --- Helper: Get Language Info ---
const getLanguageFlag = (code?: string) => SUPPORTED_LANGUAGES.find(l => l.code === code)?.flag || '🌐';
const getLanguageName = (code?: string) => SUPPORTED_LANGUAGES.find(l => l.code === code)?.name || code?.toUpperCase();

// --- Consistency Heatmap Component ---
const ConsistencyHeatmap = ({ plans }: { plans: Record<string, DailyPlan> }) => {
    const today = new Date();
    const currentYear = today.getFullYear();
    const startDate = new Date(currentYear, 0, 1);
    const startDayOfWeek = startDate.getDay(); 
    const gridStart = new Date(startDate);
    gridStart.setDate(startDate.getDate() - startDayOfWeek);

    const getDateKey = (date: Date) => {
        const y = date.getFullYear();
        const m = String(date.getMonth() + 1).padStart(2, '0');
        const d = String(date.getDate()).padStart(2, '0');
        return `${y}-${m}-${d}`;
    };

    const getActivityLevel = (date: Date) => {
        const key = getDateKey(date);
        const plan = plans[key];
        if (!plan) return 0;
        const completedTasks = plan.tasks?.filter(t => t.completed) || [];
        if (completedTasks.length === 0) return 0;
        const duration = completedTasks.reduce((acc, t) => acc + (Number(t.durationMinutes) || 0), 0);
        if (duration < 15) return 1;
        if (duration < 30) return 2;
        if (duration < 60) return 3;
        return 4;
    };

    const getLevelColor = (level: number) => {
        switch(level) {
            case 1: return 'bg-teal-100';
            case 2: return 'bg-teal-300';
            case 3: return 'bg-teal-500';
            case 4: return 'bg-teal-700';
            default: return 'bg-slate-50';
        }
    };

    const weeks = [];
    let currentDate = new Date(gridStart);
    for (let w = 0; w < 53; w++) {
        const week = [];
        for (let d = 0; d < 7; d++) {
            week.push(new Date(currentDate));
            currentDate.setDate(currentDate.getDate() + 1);
        }
        weeks.push(week);
    }

    const monthLabels: { label: string; offset: number }[] = [];
    let lastMonth = -1;

    weeks.forEach((week, weekIndex) => {
        const firstDayOfWeek = week[0];
        if (firstDayOfWeek.getFullYear() === currentYear) {
            const m = firstDayOfWeek.getMonth();
            if (m !== lastMonth) {
                monthLabels.push({ 
                    label: firstDayOfWeek.toLocaleString('en-US', { month: 'short' }), 
                    offset: weekIndex 
                });
                lastMonth = m;
            }
        }
    });

    return (
        <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h3 className="font-bold text-slate-900 text-lg">Habit Formation</h3>
                    <p className="text-xs text-slate-400 font-medium">Visualization of your low-stress consistent effort.</p>
                </div>
                <div className="flex items-center gap-2 text-[10px] text-slate-400 font-bold uppercase tracking-widest">
                    <span>Minimal</span>
                    <div className="flex gap-0.5">
                        <div className="w-3 h-3 rounded-sm bg-slate-100"></div>
                        <div className="w-3 h-3 rounded-sm bg-teal-100"></div>
                        <div className="w-3 h-3 rounded-sm bg-teal-300"></div>
                        <div className="w-3 h-3 rounded-sm bg-teal-500"></div>
                        <div className="w-3 h-3 rounded-sm bg-teal-700"></div>
                    </div>
                    <span>Intense</span>
                </div>
            </div>

            <div className="overflow-x-auto custom-scrollbar pb-2">
                <div className="min-w-max">
                    <div className="flex mb-2">
                         <div className="w-8 shrink-0"></div>
                         <div className="relative flex-1 h-4">
                             {monthLabels.map((m, i) => (
                                 <span key={i} style={{ left: `${m.offset * 18}px` }} className="absolute text-[10px] font-bold text-slate-400">
                                     {m.label}
                                 </span>
                             ))}
                         </div>
                    </div>
                    <div className="flex gap-1">
                        <div className="flex flex-col gap-0.5 w-8 text-[9px] font-bold text-slate-300 text-right pr-2 shrink-0">
                             <div className="h-4"></div>
                             <div className="h-4 leading-4">M</div>
                             <div className="h-4"></div>
                             <div className="h-4 leading-4">W</div>
                             <div className="h-4"></div>
                             <div className="h-4 leading-4">F</div>
                             <div className="h-4"></div>
                        </div>
                        <div className="flex gap-0.5">
                            {weeks.map((week, wIdx) => (
                                <div key={wIdx} className="flex flex-col gap-0.5">
                                    {week.map((day, dIdx) => {
                                        const isCurrentYear = day.getFullYear() === currentYear;
                                        const level = isCurrentYear ? getActivityLevel(day) : 0;
                                        return (
                                            <div key={dIdx} className={`w-4 h-4 rounded-sm ${isCurrentYear ? getLevelColor(level) : 'bg-transparent'} transition-all hover:ring-2 hover:ring-indigo-400`}></div>
                                        );
                                    })}
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

const RadarChart = ({ stats }: { stats: { label: string; value: number }[] }) => {
    const size = 300;
    const center = size / 2;
    const radius = 80; 
    const angleStep = (Math.PI * 2) / stats.length;
    const points = stats.map((stat, i) => {
      const angle = i * angleStep - Math.PI / 2;
      const value = Math.max(5, Math.min(stat.value, 100)) / 100; 
      const r = value * radius;
      return `${center + r * Math.cos(angle)},${center + r * Math.sin(angle)}`;
    }).join(' ');
    return (
      <svg width="100%" height="240" viewBox={`0 0 ${size} ${size}`}>
        {[0.25, 0.5, 0.75, 1].map((scale, idx) => (
             <polygon key={idx} points={stats.map((_, i) => `${center + radius * scale * Math.cos(i * angleStep - Math.PI / 2)},${center + radius * scale * Math.sin(i * angleStep - Math.PI / 2)}`).join(' ')} fill="none" stroke="#F1F5F9" strokeWidth="1" />
        ))}
        <polygon points={points} fill="rgba(79, 70, 229, 0.1)" stroke="#4F46E5" strokeWidth="2" strokeLinejoin="round" />
        {stats.map((stat, i) => {
            const angle = i * angleStep - Math.PI / 2;
            const tx = center + (radius + 25) * Math.cos(angle);
            const ty = center + (radius + 25) * Math.sin(angle);
            return <text key={i} x={tx} y={ty} textAnchor="middle" dominantBaseline="middle" className="text-[10px] font-bold fill-slate-400 uppercase tracking-widest">{stat.label}</text>;
        })}
      </svg>
    );
};

