          else if (['Vocabulary', 'Grammar'].includes(t.type || '')) areaMap['Recall'] += 3;
      });
      return Object.entries(areaMap).map(([label, value]) => ({ label, value: Math.min(100, value) }));
  }, [allCompletedTasks]);

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-10">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
          <div>
              <h1 className="text-3xl font-bold text-slate-900 tracking-tight">LinguaSphere Control Center</h1>
              <p className="text-slate-400 font-medium">Low Friction Entry. High Growth Exit.</p>
          </div>
          <div className="bg-indigo-600 px-6 py-3 rounded-2xl text-white shadow-xl shadow-indigo-500/20 flex items-center gap-4 group cursor-pointer hover:scale-[1.02] transition-all">
              <div className="text-2xl animate-pulse">🧠</div>
              <div>
                  <div className="text-[10px] font-bold text-indigo-200 uppercase tracking-widest">Mindset Refraction</div>
                  <div className="text-sm font-bold italic leading-tight">{mindset}</div>
              </div>
          </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {[
