              <div className="text-2xl animate-pulse">🧠</div>
              <div>
                  <div className="text-[10px] font-bold text-indigo-200 uppercase tracking-widest">Mindset Refraction</div>
                  <div className="text-sm font-bold italic leading-tight">{mindset}</div>
              </div>
          </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {[
              { label: 'Time Invested', val: totalHours, unit: 'h', icon: '⏱', color: 'indigo' },
              { label: 'Today Progress', val: todayCompleted, max: todayTotal, unit: 'tasks', icon: '🎯', color: 'teal' },
              { label: 'Active Tracks', val: userProfile.targetLanguages.length, unit: 'langs', icon: '🌐', color: 'purple' },
              { label: 'Growth Streak', val: 7, unit: 'days', icon: '🔥', color: 'orange' }
