  },
  {
    id: 'h4',
    type: 'Article',
    title: 'The Polyglot Routine: 15 Minutes is Enough',
    content: 'Consistency beats intensity. Learn how to structure a 15-minute daily "High Challenge" block that gives you 80% of the results of a 2-hour cramming session.',
    author: 'Dr. Polyglot',
    date: '2024-05-12',
    tags: ['Efficiency', 'Routine'],
    thumbnail: '⏱️'
  }
];

const KnowledgeHub: React.FC<KnowledgeHubProps> = ({ resources, setResources, addFlashcards, addQuizzes, nativeLanguage }) => {
  const [items, setItems] = useState<HubItem[]>(INITIAL_HUB_ITEMS);
  const [filter, setFilter] = useState<HubItemType | 'All'>('All');
  const [isProcessing, setIsProcessing] = useState<string | null>(null);

  const filteredItems = useMemo(() => {
    return filter === 'All' ? items : items.filter(i => i.type === filter);
  }, [items, filter]);

  const handleTransformToResource = async (item: HubItem) => {
    setIsProcessing(item.id);
    try {
      const langName = SUPPORTED_LANGUAGES.find(l => l.code === nativeLanguage)?.name || 'English';

      // 1. Convert HubItem to a permanent Resource
      const newResource: Resource = {
        id: `res-${item.id}`,
        title: item.title,
        type: (item.type === 'Video' ? 'Video' : 'Article') as ResourceType,
        language: item.language || 'en',
        url: item.url,
        status: 'in-progress',
        progress: 0,
        addedAt: new Date().toISOString(),
        notes: item.content,
        tags: item.tags,
        skills: ['Reading', 'Vocabulary']
      };

      // 2. AI Extraction of Assets (Flashcards & Quizzes)
      const assets = await generateLearningAssets(item.content, newResource.type, langName);

      if (assets.flashcards) {
        addFlashcards(assets.flashcards.map((f: any) => ({
          ...f, 
          id: Math.random().toString(), 
          resourceId: newResource.id, 
          resourceTitle: newResource.title, 
          masteryLevel: 'new'
        })));
      }
      if (assets.quizzes) {
        addQuizzes(assets.quizzes.map((q: any) => ({
          ...q, 
          id: Math.random().toString(), 
          resourceId: newResource.id, 
          resourceTitle: newResource.title
        })));
      }

      setResources(prev => {
          if (prev.find(r => r.id === newResource.id)) return prev;
          return [...prev, newResource];
      });

      alert(`Successfully transformed into a study Resource! Check your Library and Flashcards.`);
    } catch (e) {
      alert("AI Transformation failed. Check your API key.");
    } finally {
      setIsProcessing(null);
    }
  };

  return (
    <div className="space-y-6 h-full flex flex-col">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
        <div>
           <h2 className="text-3xl font-bold text-slate-800 tracking-tight">Knowledge Hub</h2>
           <p className="text-slate-500 font-medium">From information to intelligence. Transform consumption into production.</p>
        </div>
        <div className="flex gap-2 p-1 bg-slate-100 rounded-xl">
             {['All', 'News', 'Tutorial', 'Video', 'Article'].map(f => (
                 <button 
                    key={f}
                    onClick={() => setFilter(f as any)}
                    className={`px-4 py-2 text-xs font-bold uppercase rounded-lg transition-all ${filter === f ? 'bg-white shadow-sm text-slate-800' : 'text-slate-400 hover:text-slate-600'}`}
                 >
                     {f}
                 </button>
             ))}
        </div>
      </header>

      <div className="flex-1 overflow-y-auto pb-10">
          <div className="columns-1 md:columns-2 lg:columns-3 gap-6 space-y-6">
              {filteredItems.map(item => (
                  <div key={item.id} className="break-inside-avoid bg-white rounded-3xl border border-slate-200 shadow-sm hover:shadow-lg hover:border-indigo-300 transition-all overflow-hidden flex flex-col group">
                      <div className="p-6">
                          <div className="flex justify-between items-start mb-4">
                              <span className="w-10 h-10 rounded-xl bg-slate-50 flex items-center justify-center text-xl border border-slate-100">
                                  {item.thumbnail}
                              </span>
                              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{item.type}</span>
                          </div>
                          <h3 className="font-bold text-lg text-slate-800 mb-3 group-hover:text-indigo-600 transition-colors leading-tight">{item.title}</h3>
                          <p className="text-sm text-slate-600 leading-relaxed mb-4 line-clamp-4">
                              {item.content}
                          </p>
                          <div className="flex flex-wrap gap-2 mb-6">
                              {item.tags.map(t => (
                                  <span key={t} className="text-[10px] font-bold text-indigo-400 bg-indigo-50 px-2 py-0.5 rounded border border-indigo-100">#{t}</span>
                              ))}
                          </div>
                          <div className="flex justify-between items-center pt-4 border-t border-slate-50">
                              <div className="text-[10px] font-bold text-slate-400 uppercase">
                                  By {item.author} • {item.date}
                              </div>
                              <button 
                                onClick={() => handleTransformToResource(item)}
                                disabled={isProcessing === item.id}
                                className={`px-4 py-2 rounded-xl text-[10px] font-bold uppercase tracking-widest transition-all ${
                                    isProcessing === item.id 
                                    ? 'bg-amber-100 text-amber-600 cursor-not-allowed'
                                    : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-lg shadow-indigo-500/20'
                                }`}
                              >
                                  {isProcessing === item.id ? 'Processing...' : '✨ AI Transform'}
                              </button>
                          </div>
                      </div>
                  </div>
              ))}
          </div>
      </div>
    </div>
  );
};

