// Helper for local storage
const loadState = <T,>(key: string, fallback: T): T => {
    try {
        const saved = localStorage.getItem(key);
        return saved ? JSON.parse(saved) : fallback;
    } catch (e) {
        console.error(`Failed to load ${key}`, e);
        return fallback;
    }
};

const App: React.FC = () => {
  // Load states from localStorage or fall back to INITIAL constants
  const [userProfile, setUserProfile] = useState<UserProfile | null>(() => loadState('linguasphere_profile', null));

  const [resources, setResources] = useState<Resource[]>(() => loadState('linguasphere_resources', INITIAL_RESOURCES));
  const [projects, setProjects] = useState<Project[]>(() => loadState('linguasphere_projects', INITIAL_PROJECTS));
  const [plans, setPlans] = useState<Record<string, DailyPlan>>(() => loadState('linguasphere_plans', INITIAL_PLANS));
  const [areas, setAreas] = useState<Area[]>(() => loadState('linguasphere_areas', INITIAL_AREAS));
  const [flashcards, setFlashcards] = useState<Flashcard[]>(() => loadState('linguasphere_flashcards', []));
  const [quizzes, setQuizzes] = useState<QuizQuestion[]>(() => loadState('linguasphere_quizzes', []));

  const [currentView, setCurrentView] = useState<AppView>(AppView.DASHBOARD);

  // PERSISTENT CHAT HISTORY
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>(() => loadState('linguasphere_chat', [{ id: '1', role: 'model', text: 'Welcome back! How should we split your focus today?', timestamp: Date.now() }]));

  // --- Persistence Effects ---
  useEffect(() => { if (userProfile) localStorage.setItem('linguasphere_profile', JSON.stringify(userProfile)); }, [userProfile]);
  useEffect(() => localStorage.setItem('linguasphere_resources', JSON.stringify(resources)), [resources]);
  useEffect(() => localStorage.setItem('linguasphere_projects', JSON.stringify(projects)), [projects]);
  useEffect(() => localStorage.setItem('linguasphere_plans', JSON.stringify(plans)), [plans]);
  useEffect(() => localStorage.setItem('linguasphere_areas', JSON.stringify(areas)), [areas]);
  useEffect(() => localStorage.setItem('linguasphere_flashcards', JSON.stringify(flashcards)), [flashcards]);
  useEffect(() => localStorage.setItem('linguasphere_quizzes', JSON.stringify(quizzes)), [quizzes]);
  useEffect(() => localStorage.setItem('linguasphere_chat', JSON.stringify(chatMessages)), [chatMessages]);

  const handleOnboardingComplete = (profile: UserProfile) => setUserProfile(profile);
  const handleUpdateProfile = (profile: UserProfile) => setUserProfile(profile);

  // --- Data Import Handler ---
  const handleImportData = (data: any) => {
      try {
          if (data.userProfile) localStorage.setItem('linguasphere_profile', JSON.stringify(data.userProfile));
          if (data.resources) localStorage.setItem('linguasphere_resources', JSON.stringify(data.resources));
          if (data.projects) localStorage.setItem('linguasphere_projects', JSON.stringify(data.projects));
          if (data.plans) localStorage.setItem('linguasphere_plans', JSON.stringify(data.plans));
          if (data.areas) localStorage.setItem('linguasphere_areas', JSON.stringify(data.areas));
          if (data.flashcards) localStorage.setItem('linguasphere_flashcards', JSON.stringify(data.flashcards));
          if (data.quizzes) localStorage.setItem('linguasphere_quizzes', JSON.stringify(data.quizzes));
          if (data.chatMessages) localStorage.setItem('linguasphere_chat', JSON.stringify(data.chatMessages));

          if (data.userProfile) setUserProfile(data.userProfile);
          if (data.resources) setResources(data.resources);
          if (data.projects) setProjects(data.projects);
          if (data.plans) setPlans(data.plans);
          if (data.areas) setAreas(data.areas);
          if (data.flashcards) setFlashcards(data.flashcards);
          if (data.quizzes) setQuizzes(data.quizzes);
          if (data.chatMessages) setChatMessages(data.chatMessages);

          alert("✅ Data successfully restored!");
      } catch (e) {
          console.error("Import failed", e);
          alert("Failed to import data. Invalid format.");
      }
  };

  const fullData = { 
      userProfile, 
      resources, 
      projects, 
      plans, 
      areas, 
      flashcards, 
      quizzes, 
      chatMessages 
  };

  if (!userProfile && !localStorage.getItem('linguasphere_profile')) {
      return <Onboarding onComplete={handleOnboardingComplete} />;
  }

  const safeProfile = userProfile || DEFAULT_PROFILE;

  return (
    <div className="flex h-screen bg-[#F8FAFC]">
      {!userProfile ? (
        <Onboarding onComplete={handleOnboardingComplete} />
      ) : (
        <>
          <Navigation currentView={currentView} setView={setCurrentView} />
          <main className="flex-1 ml-64 p-8 overflow-y-auto h-screen">
             <div className="max-w-7xl mx-auto h-full">
                {currentView === AppView.DASHBOARD && (
                    <Dashboard 
                      plans={plans} 
                      projects={projects} 
                      resources={resources} 
                      areas={areas} 
                      userProfile={safeProfile}
                      flashcards={flashcards}
                    />
                )}
                {currentView === AppView.PLANNER && <Planner resources={resources} plans={plans} setPlans={setPlans} userProfile={safeProfile} projects={projects} areas={areas} />}
                {currentView === AppView.CHAT_COACH && <ChatCoach messages={chatMessages} setMessages={setChatMessages} plans={plans} nativeLanguage={safeProfile.nativeLanguage} />}
                {currentView === AppView.RESOURCES && (
                    <ResourceHub 
                        resources={resources} 
                        setResources={setResources} 
                        addFlashcards={(c) => setFlashcards(prev => [...prev, ...c])} 
                        addQuizzes={(q) => setQuizzes(prev => [...prev, ...q])} 
                        deleteFlashcard={(id) => setFlashcards(prev => prev.filter(f => f.id !== id))}
                        deleteQuiz={(id) => setQuizzes(prev => prev.filter(q => q.id !== id))}
                        flashcards={flashcards} 
                        quizzes={quizzes} 
                        nativeLanguage={safeProfile.nativeLanguage}
                    />
                )}
                {currentView === AppView.KNOWLEDGE_HUB && (
                    <KnowledgeHub 
                        resources={resources}
                        setResources={setResources}
                        addFlashcards={(c) => setFlashcards(prev => [...prev, ...c])}
                        addQuizzes={(q) => setQuizzes(prev => [...prev, ...q])}
                        nativeLanguage={safeProfile.nativeLanguage}
                    />
                )}
                {currentView === AppView.FLASHCARDS && (
                    <FlashcardDeck 
                        cards={flashcards} 
                        onUpdateCard={(updated) => setFlashcards(prev => prev.map(c => c.id === updated.id ? updated : c))} 
                    />
                )}
                {currentView === AppView.QUIZ && (
                    <QuizArena 
                        quizzes={quizzes} 
                        onAnswerQuiz={(id, answer) => setQuizzes(prev => prev.map(q => q.id === id ? { ...q, userAnswer: answer } : q))}
                        onUpdateQuiz={(updated) => setQuizzes(prev => prev.map(q => q.id === updated.id ? updated : q))}
                        onResetQuiz={(id) => setQuizzes(prev => prev.map(q => {
                            if (id && q.id !== id) return q;
                            const { userAnswer, ...rest } = q;
                            return rest as QuizQuestion;
                        }))}
                        onDeleteQuiz={(id) => setQuizzes(prev => prev.filter(q => q.id !== id))}
                    />
                )}
                {currentView === AppView.PROJECTS && (
                    <ProjectBoard 
                        projects={projects} 
                        resources={resources} 
                        areas={areas} 
                        onAddProject={(p) => setProjects(prev => [...prev, p])} 
                        onUpdateProject={(p) => setProjects(prev => prev.map(pj => pj.id === p.id ? p : pj))} 
                        onDeleteProject={(id) => setProjects(prev => prev.filter(p => p.id !== id))} 
                    />
                )}
                {currentView === AppView.AREAS && <AreaHub areas={areas} onUpdateArea={(a) => setAreas(prev => prev.map(ar => ar.id === a.id ? a : ar))} userLevel={safeProfile.cefrLevel} projects={projects} resources={resources} plans={plans} nativeLanguage={safeProfile.nativeLanguage} />}
                {currentView === AppView.PROFILE && (
                    <Profile 
                        userProfile={safeProfile} 
                        onUpdateProfile={handleUpdateProfile} 
                        fullData={fullData}
                        onImportData={handleImportData}
                    />
                )}
                {currentView === AppView.SETTINGS && (
                    <Settings 
                        userProfile={safeProfile} 
                        onUpdateProfile={handleUpdateProfile} 
                        fullData={fullData}
                        onImportData={handleImportData}
                    />
                )}
                {currentView === AppView.ROADMAP && <RoadmapView userProfile={safeProfile} onUpdateProfile={handleUpdateProfile} setView={setCurrentView} />}
             </div>
          </main>
        </>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { UserProfile } from '../types';
import { validateApiKey } from '../services/geminiService';

interface SettingsProps {
  userProfile: UserProfile;
  onUpdateProfile: (profile: UserProfile) => void;
  fullData?: any;
  onImportData?: (data: any) => void;
}

const Settings: React.FC<SettingsProps> = ({ userProfile, onUpdateProfile, fullData, onImportData }) => {
  const [formData, setFormData] = useState<UserProfile>(userProfile);
  const [isSaved, setIsSaved] = useState(false);

  // API Key State
  const [isKeyVisible, setIsKeyVisible] = useState(false);
  const [testStatus, setTestStatus] = useState<'idle' | 'testing' | 'success' | 'error'>('idle');

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    setFormData(userProfile);
  }, [userProfile]);

  const handleSave = () => {
    onUpdateProfile(formData);
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 3000);
  };

  const updateGoogleKey = (value: string) => {
      setFormData(prev => ({
          ...prev,
          apiKeys: {
              ...prev.apiKeys,
              google: value
          }
      }));
      setTestStatus('idle'); // Reset test status on change
  };

  const handleTestConnection = async () => {
      const key = formData.apiKeys?.google;
      if (!key) {
          alert("Please enter a valid Google API Key.");
          return;
      }

      setTestStatus('testing');

      const isValid = await validateApiKey(key);
      setTestStatus(isValid ? 'success' : 'error');
      if (isValid) {
          // Auto-save if valid
          onUpdateProfile(formData);
      }
  };

  // --- Import / Export Handlers ---
  const handleExport = () => {
      if (!fullData) return;
      const jsonString = JSON.stringify(fullData, null, 2);
      const blob = new Blob([jsonString], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `linguasphere_backup_${new Date().toISOString().split('T')[0]}.json`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
  };

  const handleImportClick = () => {
      fileInputRef.current?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = (event) => {
          try {
              const json = JSON.parse(event.target?.result as string);
              if (onImportData) onImportData(json);
          } catch (error) {
              alert("Invalid JSON file.");
          }
      };
      reader.readAsText(file);
      // Reset input
      if (e.target) e.target.value = '';
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 pb-10">
      <div className="flex justify-between items-center bg-white rounded-2xl p-6 shadow-sm border border-slate-200">
            <div>
                 <h2 className="text-2xl font-bold text-slate-800">Settings</h2>
                 <p className="text-slate-500 text-sm">Configure Neural Engine & Data.</p>
            </div>
            <button 
                onClick={handleSave}
                className="bg-[#6366f1] text-white px-6 py-3 rounded-xl font-bold hover:bg-indigo-700 transition-colors shadow-lg shadow-indigo-500/30 flex items-center gap-2"
            >
                {isSaved ? 'Saved! ✓' : 'Save Changes'}
            </button>
      </div>

      <div className="space-y-6">

            {/* API KEY VAULT */}
            <div className="bg-white rounded-3xl p-8 border border-slate-200 shadow-sm relative overflow-hidden flex flex-col min-h-[300px]">
                {/* Subtle Decorative Background */}
                <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-50 rounded-full blur-3xl -mr-16 -mt-16 pointer-events-none opacity-60"></div>

                <div className="relative z-10 flex justify-between items-start mb-6 border-b border-slate-100 pb-4">
                     <div>
                         <h3 className="text-xl font-bold mb-1 text-slate-800 flex items-center gap-2">
                             <span>🔑</span> Google Gemini Configuration
                         </h3>
                         <p className="text-slate-500 text-sm">LinguaSphere uses Google Gemini Flash for fast, efficient coaching.</p>
                     </div>
                </div>

                <div className="relative z-10 flex-1 flex flex-col space-y-6">

                     {/* Key Input */}
                     <div className="flex-1">
                         <label className="block text-[10px] font-bold text-slate-400 uppercase mb-2 tracking-widest flex justify-between">
                             <span>Google API Key</span>
                             <a href="https://aistudio.google.com/app/apikey" target="_blank" rel="noreferrer" className="text-indigo-600 hover:underline cursor-pointer">Get API Key →</a>
                         </label>
                         <div className="relative group">
                             <input 
                                 type={isKeyVisible ? "text" : "password"}
                                 value={formData.apiKeys?.google || ''}
                                 onChange={(e) => updateGoogleKey(e.target.value)}
                                 placeholder="Enter your Google Gemini API Key (begins with AIza...)"
                                 className="w-full bg-slate-50 border border-slate-200 rounded-xl p-4 pr-12 text-sm text-slate-800 placeholder-slate-400 focus:border-indigo-500 focus:outline-none focus:ring-1 focus:ring-indigo-500/50 transition-all font-mono"
                             />
                             <button 
                                 onClick={() => setIsKeyVisible(!isKeyVisible)}
                                 className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-indigo-600 transition-colors"
                             >
                                 {isKeyVisible ? '🙈' : '👁️'}
                             </button>
                         </div>
                         <p className="text-xs text-slate-400 mt-2">
                             Your key is stored locally in your browser and used directly with the Google Gemini API. It is never sent to our servers.
                         </p>
                     </div>

                     {/* Action Bar */}
                     <div className="pt-4 border-t border-slate-100 flex items-center justify-between">
                         <div className="flex items-center gap-2">
                             {testStatus === 'testing' && <span className="text-amber-500 text-xs font-bold animate-pulse">● Connecting...</span>}
                             {testStatus === 'success' && <span className="text-green-500 text-xs font-bold">● Connection Verified</span>}
                             {testStatus === 'error' && <span className="text-red-500 text-xs font-bold">● Connection Failed</span>}
                         </div>
                         <button 
                             onClick={handleTestConnection}
                             disabled={testStatus === 'testing' || !formData.apiKeys?.google}
                             className={`px-6 py-3 rounded-xl font-bold text-sm transition-all shadow-lg flex items-center gap-2 ${
                                 testStatus === 'success' 
                                 ? 'bg-green-600 hover:bg-green-700 text-white shadow-green-900/20'
                                 : testStatus === 'error'
                                 ? 'bg-red-600 hover:bg-red-700 text-white shadow-red-900/20'
                                 : 'bg-indigo-600 hover:bg-indigo-700 text-white shadow-indigo-900/30'
                             } disabled:opacity-50 disabled:cursor-not-allowed`}
                         >
                             {testStatus === 'testing' ? 'Verifying...' : testStatus === 'success' ? 'Verified & Saved' : 'Verify & Save'}
                         </button>
                     </div>
                </div>
            </div>

            {/* DATA MANAGEMENT */}
            <div className="bg-white rounded-2xl p-6 border border-slate-200 shadow-sm">
                <h3 className="font-bold text-slate-800 text-sm mb-4">Data Management</h3>
                <div className="flex gap-3">
                     <button onClick={handleExport} className="flex-1 px-4 py-2 bg-slate-50 text-slate-700 border border-slate-200 rounded-lg font-bold text-xs hover:bg-slate-100 flex items-center justify-center gap-2 transition-colors">
                         <span>📥</span> Export Backup
                     </button>
                     <button onClick={handleImportClick} className="flex-1 px-4 py-2 bg-slate-50 text-slate-700 border border-slate-200 rounded-lg font-bold text-xs hover:bg-slate-100 flex items-center justify-center gap-2 transition-colors">
                         <span>📤</span> Restore Data
                     </button>
                     <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept=".json" />
                </div>
            </div>

            {/* Reset Data */}
            <div className="bg-red-50 rounded-2xl p-6 border border-red-100 flex justify-between items-center shadow-sm">
