export class LiveSession {
  private sessionPromise: Promise<any> | null = null;
  private inputAudioContext: AudioContext | null = null;
  private outputAudioContext: AudioContext | null = null;
  private nextStartTime = 0;
  private sources = new Set<AudioBufferSourceNode>();
  private stream: MediaStream | null = null;

  async start(onUpdate: (status: string) => void) {
    const ai = getClient();
    this.inputAudioContext = new AudioContext({sampleRate: 16000});
    this.outputAudioContext = new AudioContext({sampleRate: 24000});
    this.stream = await navigator.mediaDevices.getUserMedia({ audio: true });

    // Fixed Live Session initialization with proper callbacks and config following SDK guidelines
    this.sessionPromise = ai.live.connect({
      model: 'gemini-2.5-flash-native-audio-preview-12-2025',
      callbacks: {
        onopen: () => {
          onUpdate("Connected & Listening");
          if (this.inputAudioContext && this.stream) {
              const source = this.inputAudioContext.createMediaStreamSource(this.stream);
              const scriptProcessor = this.inputAudioContext.createScriptProcessor(4096, 1, 1);
              scriptProcessor.onaudioprocess = (audioProcessingEvent) => {
                const inputData = audioProcessingEvent.inputBuffer.getChannelData(0);
                const l = inputData.length;
                const int16 = new Int16Array(l);
                for (let i = 0; i < l; i++) {
                    int16[i] = inputData[i] * 32768;
                }
                const pcmBlob = {
                    data: encode(new Uint8Array(int16.buffer)),
                    mimeType: 'audio/pcm;rate=16000',
                };
                this.sessionPromise?.then((session) => {
                    session.sendRealtimeInput({ media: pcmBlob });
                });
              };
              source.connect(scriptProcessor);
              scriptProcessor.connect(this.inputAudioContext.destination);
          }
        },
        onmessage: async (message: LiveServerMessage) => {
          const base64EncodedAudioString = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (base64EncodedAudioString && this.outputAudioContext) {
            this.nextStartTime = Math.max(this.nextStartTime, this.outputAudioContext.currentTime);
            const audioBuffer = await decodeAudioData(
              decode(base64EncodedAudioString),
              this.outputAudioContext,
              24000,
              1,
            );
            const source = this.outputAudioContext.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(this.outputAudioContext.destination);
            source.addEventListener('ended', () => {
              this.sources.delete(source);
            });
            source.start(this.nextStartTime);
            this.nextStartTime += audioBuffer.duration;
            this.sources.add(source);
          }

          if (message.serverContent?.interrupted) {
            for (const source of this.sources.values()) {
              source.stop();
            }
            this.sources.clear();
            this.nextStartTime = 0;
          }
        },
        onerror: (e) => {
            console.error("Live session error:", e);
            onUpdate("Error");
        },
        onclose: () => onUpdate("Closed"),
      },
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {prebuiltVoiceConfig: {voiceName: 'Zephyr'}},
        },
        systemInstruction: 'You are a friendly and helpful language learning coach.',
      }
    });
  }

  async stop() {
    if (this.sessionPromise) {
        const session = await this.sessionPromise;
        session.close();
    }
    if (this.stream) {
        this.stream.getTracks().forEach(track => track.stop());
    }
    if (this.inputAudioContext) {
        this.inputAudioContext.close();
    }
    if (this.outputAudioContext) {
        this.outputAudioContext.close();
    }
    this.sources.forEach(s => s.stop());
    this.sources.clear();
  }
}

