  const [energyLevel, setEnergyLevel] = useState<'low' | 'balanced' | 'high'>('balanced');
  const [showLogModal, setShowLogModal] = useState(false);
  const [logForm, setLogForm] = useState({ description: '', duration: 30, type: 'Listening' });

  const currentPlan = plans[selectedDate];

  const handleGenerate = async () => {
    setWizardStep('generating');
    try {
      const activeProject = projects.find(p => p.status === 'active');
      const projectResources = activeProject 
        ? resources.filter(r => activeProject.resourceIds.includes(r.id))
        : resources.filter(r => r.status === 'in-progress' || r.isDailyFocus);

      const resourceDataForAI = projectResources.map(r => 
        `- [Language: ${r.language || 'General'}] Title: "${r.title}" | Type: ${r.type} | Tags: ${r.tags.join(', ')}`
      ).join('\n');

      const focusAreaNames = activeProject
          ? activeProject.areaIds.map(id => areas.find(a => a.id === id)?.name).filter(Boolean).join(', ')
          : "General Fluency";

      const priorityAreas = areas.filter(a => a.isPriority).map(a => a.name).join(', ');

      const nativeLangName = SUPPORTED_LANGUAGES.find(l => l.code === userProfile?.nativeLanguage)?.name || 'English';

      const planData = await generateStudyPlan(
          activeProject, 
          resourceDataForAI, 
          userProfile?.preferences, 
          nativeLangName, 
          energyLevel,
          focusAreaNames,
          priorityAreas // PASS PRIORITY AREAS HERE
      );

      const newPlan: DailyPlan = {
        date: selectedDate,
        focus: planData.focus || "Daily Focus",
        motivation: planData.motivation || "Keep pushing.",
        tasks: (planData.tasks || []).map((t: any) => ({
            ...t, 
            id: Date.now().toString() + Math.random(),
            completed: false,
            source: 'ai',
            resourceId: resources.find(r => r.title.trim().toLowerCase() === t.resourceTitle?.trim().toLowerCase())?.id,
            projectId: activeProject?.id,
            resourceTitle: t.resourceTitle
        }))
      };

      setPlans(prev => ({ ...prev, [selectedDate]: newPlan }));
      setWizardStep('idle');
    } catch (e) {
      console.error(e);
      setWizardStep('idle');
      alert("AI failed to plan.");
    }
  };

  const handleToggleTask = (taskId: string) => {
      if (!currentPlan) return;
      const updatedTasks = currentPlan.tasks.map(t => 
        t.id === taskId ? { ...t, completed: !t.completed, completedAt: !t.completed ? new Date().toISOString() : undefined } : t
      );
      setPlans({ ...plans, [selectedDate]: { ...currentPlan, tasks: updatedTasks } });
  };

  const handleSaveTaskNote = (taskId: string, note: string) => {
    if (!currentPlan) return;
    const updatedTasks = currentPlan.tasks.map(t => t.id === taskId ? { ...t, notes: note } : t);
    setPlans({ ...plans, [selectedDate]: { ...currentPlan, tasks: updatedTasks } });
  }

  const handleManualLog = () => {
      if (!logForm.description) return;
      const newTask: Task = { id: Date.now().toString(), description: logForm.description, durationMinutes: logForm.duration, type: logForm.type, completed: true, source: 'manual', completedAt: new Date().toISOString() };
      setPlans(prev => {
          const plan = prev[selectedDate] || { date: selectedDate, focus: 'Logged Activities', tasks: [] };
          return { ...prev, [selectedDate]: { ...plan, tasks: [...plan.tasks, newTask] } };
      });
      setShowLogModal(false);
  }

  return (
    <div className="h-full flex flex-col space-y-6">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
            <div><h2 className="text-3xl font-bold text-slate-800 tracking-tight">Daily Action Plan</h2></div>
            <div className="flex items-center gap-3">
                <button onClick={() => setShowLogModal(true)} className="bg-amber-50 border border-amber-200 text-amber-800 px-4 py-2 rounded-xl font-bold text-sm">Log Activity</button>
                <div className="bg-white px-4 py-2 rounded-xl border border-slate-200 font-bold text-slate-700 text-sm">{new Date(selectedDate).toDateString()}</div>
            </div>
        </div>

        <div className="flex-1 grid grid-cols-1 lg:grid-cols-12 gap-8 overflow-hidden">
            <div className="lg:col-span-4 flex flex-col space-y-6">
                <Calendar value={selectedDate} onChange={setSelectedDate} />
                {currentPlan && (
                    <div className="bg-indigo-600 rounded-3xl p-6 text-white shadow-xl relative overflow-hidden">
                        <div className="absolute top-0 right-0 w-24 h-24 bg-white/10 rounded-full -mr-8 -mt-8"></div>
                        <h4 className="text-xs font-bold uppercase tracking-widest text-indigo-200 mb-2">Today's Mission</h4>
                        <div className="text-xl font-bold mb-4 leading-tight">{currentPlan.focus}</div>
                        <div className="mt-6 flex justify-between items-end">
                            <div><div className="text-3xl font-bold">{currentPlan.tasks.filter(t => t.completed).length}/{currentPlan.tasks.length}</div></div>
                            <div className="text-right"><div className="text-xl font-bold text-teal-300">{Math.round((currentPlan.tasks.filter(t => t.completed).length / (currentPlan.tasks.length || 1)) * 100)}%</div></div>
                        </div>
                    </div>
                )}
            </div>

            <div className="lg:col-span-8 flex flex-col min-h-0 bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
                    <h3 className="font-bold text-slate-700">Checklist</h3>
                    {!currentPlan && wizardStep === 'idle' && (
                        <button onClick={() => setWizardStep('energy')} className="px-6 py-2 bg-indigo-600 text-white rounded-xl font-bold shadow-lg hover:bg-indigo-700 transition-all text-sm">✨ Generate with AI</button>
                    )}
                </div>

                <div className="flex-1 overflow-y-auto p-6 space-y-4 custom-scrollbar">
                    {wizardStep === 'energy' && (
                        <div className="py-12 text-center space-y-8 animate-in zoom-in-95 duration-300">
                            <div><h3 className="text-2xl font-bold text-slate-800">How is your battery today?</h3></div>
                            <div className="flex flex-wrap justify-center gap-4">
                                {[
                                    { id: 'low', label: 'Maintenance', icon: '🔋', color: 'bg-amber-100 text-amber-700 border-amber-300' },
                                    { id: 'balanced', label: 'Standard', icon: '⚡', color: 'bg-teal-100 text-teal-700 border-teal-300' },
                                    { id: 'high', label: 'Hyperfocus', icon: '🔥', color: 'bg-red-100 text-red-700 border-red-300' }
                                ].map(lvl => (
                                    <button 
                                        key={lvl.id} 
                                        onClick={() => setEnergyLevel(lvl.id as any)}
                                        className={`w-40 p-6 rounded-3xl border-2 transition-all flex flex-col items-center gap-2 ${energyLevel === lvl.id ? lvl.color : 'bg-white border-slate-200 text-slate-600 hover:border-slate-300'}`}
                                    >
                                        <span className="text-4xl">{lvl.icon}</span><span className="font-bold">{lvl.label}</span>
                                    </button>
                                ))}
                            </div>
                            <div className="flex justify-center gap-3">
                                <button onClick={() => setWizardStep('idle')} className="px-8 py-3 text-slate-400 font-bold">Cancel</button>
                                <button onClick={handleGenerate} className="px-10 py-3 bg-indigo-600 text-white rounded-xl font-bold shadow-xl">Generate Plan</button>
                            </div>
                        </div>
                    )}

                    {wizardStep === 'generating' && (
                        <div className="py-20 flex flex-col items-center gap-4 animate-pulse"><div className="text-6xl animate-bounce">🤖</div><div className="text-xl font-bold text-slate-800">Architecting your session...</div></div>
                    )}

                    {currentPlan && wizardStep === 'idle' && (
                        <div className="space-y-4">
                            {currentPlan.tasks.map(task => (
                                <TaskCard key={task.id} task={task} projectTitle={projects.find(p => p.id === task.projectId)?.title} onToggle={() => handleToggleTask(task.id)} onSaveNote={(note) => handleSaveTaskNote(task.id, note)} />
                            ))}
                            <button onClick={() => setWizardStep('energy')} className="w-full py-4 border-2 border-dashed border-slate-200 rounded-2xl text-slate-400 font-bold uppercase tracking-widest text-[10px]">↻ Regenerate Plan</button>
                        </div>
                    )}

                    {!currentPlan && wizardStep === 'idle' && <div className="py-20 text-center text-slate-400"><div className="text-5xl mb-4">💤</div><p>No activity planned.</p></div>}
                </div>
            </div>
        </div>

        {showLogModal && (
            <div className="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4">
                <div className="bg-white w-full max-w-md rounded-3xl p-8 shadow-2xl animate-in zoom-in-95">
                    <h3 className="text-2xl font-bold text-slate-800 mb-6">Manual Log</h3>
