export default Dashboard;

import React, { useMemo } from 'react';
import { DailyPlan, Project, Resource, Area, Task, UserProfile, Flashcard, SUPPORTED_LANGUAGES } from '../types';

interface DashboardProps {
  plans: Record<string, DailyPlan>;
  projects: Project[];
  resources: Resource[];
  areas: Area[];
  userProfile: UserProfile;
  flashcards: Flashcard[];
}

// --- Helper: Get Language Info ---
const getLanguageFlag = (code?: string) => SUPPORTED_LANGUAGES.find(l => l.code === code)?.flag || '🌐';
const getLanguageName = (code?: string) => SUPPORTED_LANGUAGES.find(l => l.code === code)?.name || code?.toUpperCase();

// --- Consistency Heatmap Component ---
const ConsistencyHeatmap = ({ plans }: { plans: Record<string, DailyPlan> }) => {
    const today = new Date();
    const currentYear = today.getFullYear();
    // Start from Jan 1st of current year
    const startDate = new Date(currentYear, 0, 1);

    // Align grid start to the Sunday before (or on) Jan 1st
    const startDayOfWeek = startDate.getDay(); 
    const gridStart = new Date(startDate);
    gridStart.setDate(startDate.getDate() - startDayOfWeek);

    // Helper to format date key to match Planner storage (YYYY-MM-DD)
    // We use local date string parts to avoid timezone shifting issues when visualizing local calendar
    const getDateKey = (date: Date) => {
        const y = date.getFullYear();
        const m = String(date.getMonth() + 1).padStart(2, '0');
        const d = String(date.getDate()).padStart(2, '0');
        return `${y}-${m}-${d}`;
    };

    // Helper to get activity level 0-4
    const getActivityLevel = (date: Date) => {
        const key = getDateKey(date);
        const plan = plans[key];

        // Check strict ISO key match first, if not found, try to match loose date
        // This handles cases where imported data might be strictly YYYY-MM-DD
        const effectivePlan = plan || Object.values(plans).find(p => p.date === key);

        if (!effectivePlan) return 0;

        const completedTasks = effectivePlan.tasks?.filter(t => t.completed) || [];
        if (completedTasks.length === 0) return 0;

        const duration = completedTasks.reduce((acc, t) => acc + (Number(t.durationMinutes) || 0), 0);

        // Level 1 should trigger if ANY task is completed, even if duration is 0
        if (duration === 0) return 1; 
        if (duration < 15) return 1;
        if (duration < 30) return 2;
        if (duration < 60) return 3;
        return 4;
    };

    const getLevelColor = (level: number) => {
        switch(level) {
            case 1: return 'bg-blue-200';
            case 2: return 'bg-blue-400';
            case 3: return 'bg-blue-600';
            case 4: return 'bg-blue-800';
            default: return 'bg-slate-100';
        }
    };

    // Generate 53 weeks to cover the full year
    const weeks = [];
    let currentDate = new Date(gridStart);
    for (let w = 0; w < 53; w++) {
        const week = [];
        for (let d = 0; d < 7; d++) {
            week.push(new Date(currentDate));
            currentDate.setDate(currentDate.getDate() + 1);
        }
        weeks.push(week);
    }

    // Calculate Month Label Positions
    // Grid Size Constants
    const CELL_SIZE = 16; // 16px (w-4)
    const GAP_SIZE = 2;   // 2px (gap-0.5)
    const PITCH = CELL_SIZE + GAP_SIZE;

    const monthLabels: { label: string; offset: number }[] = [];
    let lastMonth = -1;

    weeks.forEach((week, weekIndex) => {
        const firstDayOfWeek = week[0];
        // Only label months within the current year
        if (firstDayOfWeek.getFullYear() === currentYear) {
            const m = firstDayOfWeek.getMonth();
            if (m !== lastMonth) {
                monthLabels.push({ 
                    label: firstDayOfWeek.toLocaleString('en-US', { month: 'short' }), 
                    offset: weekIndex 
                });
                lastMonth = m;
            }
        } else if (weekIndex === 0 && week[6].getFullYear() === currentYear && week[6].getMonth() === 0) {
            // Edge case: Year starts mid-week, ensure Jan label appears
             monthLabels.push({ label: 'Jan', offset: 0 });
             lastMonth = 0;
        }
    });

    return (
        <div className="bg-white p-6 md:p-8 rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
            <div className="flex justify-between items-center mb-6">
                <h3 className="font-bold text-slate-900 text-lg">Study Consistency</h3>
                <div className="flex items-center gap-2 text-xs text-slate-500 font-medium">
                    <span>Less</span>
                    <div className="flex gap-0.5">
                        <div className="w-4 h-4 rounded-sm bg-slate-100"></div>
                        <div className="w-4 h-4 rounded-sm bg-blue-200"></div>
                        <div className="w-4 h-4 rounded-sm bg-blue-400"></div>
                        <div className="w-4 h-4 rounded-sm bg-blue-600"></div>
                        <div className="w-4 h-4 rounded-sm bg-blue-800"></div>
                    </div>
                    <span>More</span>
                </div>
            </div>

            <div className="overflow-x-auto custom-scrollbar pb-2">
                <div className="min-w-max">
                    {/* Top Row: Spacer for Day labels + Month Labels */}
                    <div className="flex mb-2">
                         <div className="w-8 shrink-0"></div> {/* Match width of day labels column */}
                         <div className="relative flex-1 h-6">
                             {monthLabels.map((m, i) => (
                                 <span 
                                     key={i} 
                                     style={{ left: `${m.offset * PITCH}px` }} 
                                     className="absolute text-xs font-bold text-slate-400"
                                 >
                                     {m.label}
                                 </span>
                             ))}
                         </div>
                    </div>

                    {/* Main Grid Area: Day Labels + Cells */}
                    <div className="flex gap-1">
                        {/* Day Labels Column - STRICTLY aligned with grid rows */}
                        <div className="flex flex-col gap-0.5 w-8 pt-[0px] text-[10px] font-bold text-slate-400 text-right pr-2 shrink-0">
                             {/* Indices: 0=Sun, 1=Mon, 2=Tue, 3=Wed, 4=Thu, 5=Fri, 6=Sat */}
                             <div className="h-4"></div> {/* Sun */}
                             <div className="h-4 leading-4">Mon</div>
                             <div className="h-4"></div> {/* Tue */}
                             <div className="h-4 leading-4">Wed</div>
                             <div className="h-4"></div> {/* Thu */}
                             <div className="h-4 leading-4">Fri</div>
                             <div className="h-4"></div> {/* Sat */}
                        </div>

                        {/* Heatmap Grid */}
                        <div className="flex gap-0.5">
                            {weeks.map((week, wIdx) => (
                                <div key={wIdx} className="flex flex-col gap-0.5">
                                    {week.map((day, dIdx) => {
                                        const isCurrentYear = day.getFullYear() === currentYear;
                                        const level = isCurrentYear ? getActivityLevel(day) : 0;
                                        const color = isCurrentYear ? getLevelColor(level) : 'bg-transparent';

                                        return (
                                            <div 
                                                key={dIdx}
                                                className={`w-4 h-4 rounded-sm ${color} transition-all hover:ring-2 hover:ring-slate-400 hover:z-10`}
                                                title={`${day.toDateString()}: ${level > 0 ? `Level ${level}` : 'No activity'}`}
                                            ></div>
                                        );
                                    })}
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

// --- SVG Radar Chart Component ---
const RadarChart = ({ stats }: { stats: { label: string; value: number }[] }) => {
    const size = 400;
    const center = size / 2;
    const radius = 90; 
    const angleStep = (Math.PI * 2) / stats.length;

    const points = stats.map((stat, i) => {
      const angle = i * angleStep - Math.PI / 2;
      const value = Math.max(0, Math.min(stat.value, 100)) / 100; 
      const r = value * radius;
      const x = center + r * Math.cos(angle);
      const y = center + r * Math.sin(angle);
      return `${x},${y}`;
    }).join(' ');

    const backgroundPolygons = [0.25, 0.5, 0.75, 1].map((scale, idx) => {
        const polyPoints = stats.map((_, i) => {
            const angle = i * angleStep - Math.PI / 2;
            const r = radius * scale;
            const x = center + r * Math.cos(angle);
            const y = center + r * Math.sin(angle);
            return `${x},${y}`;
        }).join(' ');
        return <polygon key={idx} points={polyPoints} fill="none" stroke="#E2E8F0" strokeWidth="1" />;
    });

    const labels = stats.map((stat, i) => {
        const angle = i * angleStep - Math.PI / 2;
        const r = radius + 35; 
        const x = center + r * Math.cos(angle);
        const y = center + r * Math.sin(angle);

        let anchor: 'start' | 'middle' | 'end' = 'middle';
        let baseline: 'auto' | 'middle' | 'hanging' = 'middle';

        if (Math.abs(x - center) < 5) anchor = 'middle';
        else if (x > center) anchor = 'start';
        else anchor = 'end';

        if (Math.abs(y - center) < 5) baseline = 'middle'; 
        else if (y < center) baseline = 'auto'; 
        else baseline = 'hanging'; 

        return (
            <text 
                key={i} 
                x={x} 
                y={y} 
                textAnchor={anchor}
                dominantBaseline={baseline}
                className="text-[12px] font-bold fill-slate-500 uppercase tracking-widest"
                style={{ filter: 'drop-shadow(0px 1px 0px white)' }}
            >
                {stat.label}
            </text>
        );
    });

    return (
      <svg width="100%" height="100%" viewBox={`0 0 ${size} ${size}`}>
        {backgroundPolygons}
        {stats.map((_, i) => {
             const angle = i * angleStep - Math.PI / 2;
             const x = center + radius * Math.cos(angle);
             const y = center + radius * Math.sin(angle);
             return <line key={`l-${i}`} x1={center} y1={center} x2={x} y2={y} stroke="#F1F5F9" strokeWidth="1" />
        })}
        <polygon points={points} fill="rgba(99, 102, 241, 0.15)" stroke="#6366f1" strokeWidth="2" strokeLinejoin="round" />
        {points.split(' ').map((p, i) => {
            const [cx, cy] = p.split(',');
            return <circle key={i} cx={cx} cy={cy} r="4" fill="#6366f1" stroke="white" strokeWidth="2" />;
        })}
        {labels}
      </svg>
    );
};

// --- Resource Usage List Component ---
const ResourceUsageList = ({ resources, plans }: { resources: Resource[], plans: Record<string, DailyPlan> }) => {
    const usageMap = useMemo(() => {
        const map: Record<string, number> = {};
        Object.values(plans).forEach(plan => {
            plan.tasks.forEach(task => {
                if (task.completed && task.resourceId) {
                    map[task.resourceId] = (map[task.resourceId] || 0) + 1;
                }
            });
        });
        return map;
    }, [plans]);

    // Show resources that are explicitly marked as Daily Focus OR are currently Active (in-progress)
    const focusResources = resources.filter(r => r.isDailyFocus || r.status === 'in-progress');

    // Sort: Daily Focus items first, then by usage count (descending)
    const sortedFocus = [...focusResources].sort((a, b) => {
        if (a.isDailyFocus && !b.isDailyFocus) return -1;
        if (!a.isDailyFocus && b.isDailyFocus) return 1;
        return ((usageMap[b.id] as number) || 0) - ((usageMap[a.id] as number) || 0);
    });

    const maxVal = Math.max(...(Object.values(usageMap) as number[]), 5); 

    return (
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col h-full min-h-[400px]">
            <div className="flex justify-between items-center mb-6">
                <h3 className="font-bold text-slate-900">Focus Resources</h3>
                <span className="text-[10px] font-bold bg-amber-50 text-amber-600 px-2 py-1 rounded border border-amber-100">ON DECK</span>
            </div>

            <div className="flex-1 space-y-5 overflow-y-auto custom-scrollbar">
                {sortedFocus.map(res => {
                    const count = usageMap[res.id] || 0;
                    const percent = Math.min(100, (count / maxVal) * 100);

                    return (
                        <div key={res.id} className="group">
                            <div className="flex justify-between text-xs font-bold text-slate-700 mb-2">
                                <span className="truncate pr-2 flex items-center gap-2">
                                    <span className="text-base">{getLanguageFlag(res.language)}</span>
                                    {res.title}
                                    {res.isDailyFocus && <span className="text-[8px] bg-teal-100 text-teal-700 px-1 rounded">FOCUS</span>}
                                </span>
                                <span className="text-slate-400">{count} sessions</span>
                            </div>
                            <div className="w-full bg-slate-100 rounded-full h-2.5 overflow-hidden">
                                <div 
                                    className={`h-full rounded-full transition-all duration-1000 ${
                                        res.language === 'ja' ? 'bg-red-400 group-hover:bg-red-500' :
                                        res.language === 'en' ? 'bg-blue-400 group-hover:bg-blue-500' :
                                        'bg-amber-400 group-hover:bg-amber-500'
                                    }`} 
                                    style={{ width: `${Math.max(5, percent)}%` }} 
                                ></div>
                            </div>
                        </div>
                    );
                })}

                {sortedFocus.length === 0 && (
                    <div className="flex flex-col items-center justify-center h-full text-slate-400 text-center py-8">
                        <span className="text-4xl mb-3 opacity-30">🎯</span>
                        <p className="text-sm font-bold text-slate-600">No Focus Resources</p>
                        <p className="text-xs mt-1">Mark resources as 'Daily Focus' or 'Active' in the Library.</p>
                    </div>
                )}
            </div>
             <div className="mt-auto pt-4 border-t border-slate-50 text-center">
                <p className="text-[10px] text-slate-400 font-medium">Flag indicates resource language</p>
            </div>
        </div>
    )
}

const Dashboard: React.FC<DashboardProps> = ({ plans = {}, projects = [], resources = [], areas = [], userProfile, flashcards = [] }) => {

  // --- Calculate Metrics ---
  const allCompletedTasks = useMemo(() => {
    const tasks: Task[] = [];
    (Object.values(plans || {}) as DailyPlan[]).forEach(plan => {
      (plan?.tasks || []).forEach(task => {
        if (task.completed) tasks.push(task);
      });
    });
    return tasks;
  }, [plans]);

  // Fix: Explicitly cast durationMinutes to Number to avoid type errors
  const totalHours = Math.round(allCompletedTasks.reduce((acc: number, t) => acc + (Number(t.durationMinutes) || 0), 0) / 60); 

  // --- Real Streak Calculation ---
  const streak = useMemo(() => {
    // 1. Get all dates that have at least one completed task
    const activeDates = (Object.values(plans) as DailyPlan[])
        .filter(plan => plan.tasks.some(t => t.completed))
        .map(plan => plan.date)
        .sort(); // Sort string dates YYYY-MM-DD

    if (activeDates.length === 0) return 0;

    // 2. Helper to get YYYY-MM-DD for a Date object
    const getISO = (d: Date) => d.toISOString().split('T')[0];

    const today = new Date();
    const todayStr = getISO(today);

    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    const yesterdayStr = getISO(yesterday);

    // If no activity today AND no activity yesterday, streak is broken -> 0
    if (!activeDates.includes(todayStr) && !activeDates.includes(yesterdayStr)) {
        return 0;
    }

    // 3. Count backwards
    let currentStreak = 0;

    // Start checking from Today if active, otherwise start from Yesterday
    let checkDate = activeDates.includes(todayStr) ? today : yesterday;

    while (true) {
        const checkStr = getISO(checkDate);
        if (activeDates.includes(checkStr)) {
            currentStreak++;
            // Move back one day
            checkDate.setDate(checkDate.getDate() - 1);
        } else {
            break; 
        }
    }

    return currentStreak;
  }, [plans]);

  // --- Breakdown Hours by Language ---
  const hoursByLanguage = useMemo((): Record<string, number> => {
      const map: Record<string, number> = {};
      allCompletedTasks.forEach(t => {
         // Resolve language from Resource -> Project -> Native
         let lang = 'en'; // Default
         if (t.resourceId) {
             const res = resources.find(r => r.id === t.resourceId);
             if (res) lang = res.language;
         } else if (t.projectId) {
             const proj = projects.find(p => p.id === t.projectId);
             if (proj) lang = proj.language;
         }

         // Fix: Explicitly cast durationMinutes to Number
         const currentDuration: number = Number(t.durationMinutes) || 0;
         const currentTotal: number = map[lang] || 0;
         map[lang] = currentTotal + currentDuration;
      });
      return map;
  }, [allCompletedTasks, resources, projects]);

  const sortedLanguages = Object.entries(hoursByLanguage).sort((a,b) => (b[1] as number) - (a[1] as number));

  // --- Daily Plan Stats ---
  const today = new Date().toISOString().split('T')[0];
  const todayPlan = plans[today];
  const todayTotal = todayPlan?.tasks?.length || 0;
  const todayCompleted = todayPlan?.tasks?.filter(t => t.completed).length || 0;

  // --- Calculate Radar Stats ---
  const radarStats = useMemo(() => {
      const areaMap: Record<string, number> = { 'READING': 30, 'WRITING': 30, 'LISTENING': 30, 'SPEAKING': 30 };
      allCompletedTasks.forEach(t => {
          let type = 'READING';
          if (t.type?.toLowerCase().includes('listen')) type = 'LISTENING';
          else if (t.type?.toLowerCase().includes('speak')) type = 'SPEAKING';
          else if (t.type?.toLowerCase().includes('writ')) type = 'WRITING';
          else if (t.type?.toLowerCase().includes('read')) type = 'READING';

          const currentVal = areaMap[type];
          if (currentVal !== undefined) {
             areaMap[type] = Math.min(100, currentVal + 5);
          }
      });
      return [
          { label: 'READING', value: areaMap['READING'] },
          { label: 'WRITING', value: areaMap['WRITING'] },
          { label: 'SPEAKING', value: areaMap['SPEAKING'] },
          { label: 'LISTENING', value: areaMap['LISTENING'] },
      ];
  }, [allCompletedTasks]);

  const getDaysDue = (deadline?: string) => {
      if (!deadline) return 'Self-Paced';
      const diff = new Date(deadline).getTime() - Date.now();
      const days = Math.ceil(diff / (1000 * 3600 * 24));
      if (days < 0) return 'Overdue';
      if (days === 0) return 'Due Today';
      return `${days} days left`;
  };

  const getProjectProgress = (p: Project) => {
      if (p.resourceIds.length === 0) return 0;
      const linked = resources.filter(r => p.resourceIds.includes(r.id));
      if (linked.length === 0) return 0;
      const totalProg = linked.reduce((acc, r) => acc + r.progress, 0);
      return Math.round(totalProg / linked.length);
  };

  // Styles based on language
  const getProjectStyle = (lang: string) => {
      if (lang === 'ja') return { bg: 'bg-red-50', text: 'text-red-700', bar: 'bg-red-500', icon: 'bg-red-100 text-red-600', border: 'border-red-100' };
      if (lang === 'en') return { bg: 'bg-blue-50', text: 'text-blue-700', bar: 'bg-blue-500', icon: 'bg-blue-100 text-blue-600', border: 'border-blue-100' };
      if (lang === 'es') return { bg: 'bg-yellow-50', text: 'text-yellow-700', bar: 'bg-yellow-500', icon: 'bg-yellow-100 text-yellow-600', border: 'border-yellow-100' };
      // Default
      return { bg: 'bg-indigo-50', text: 'text-indigo-700', bar: 'bg-indigo-500', icon: 'bg-indigo-100 text-indigo-600', border: 'border-slate-100' };
  }

  return (
    <div className="space-y-6 font-inter text-slate-800 animate-in fade-in duration-500 pb-10">

      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6 mb-2">
          <div>
              <h1 className="text-3xl font-bold text-slate-900 mb-1">Good Morning, {userProfile.name?.split(' ')[0] || 'Learner'}</h1>
              <p className="text-slate-500 font-medium">Your {userProfile.targetLanguages.length > 1 ? 'polyglot' : 'fluency'} engine is running smooth.</p>
          </div>

          <div className="bg-slate-50 border border-slate-200 px-4 py-3 rounded-2xl flex items-center gap-4 shadow-sm hover:shadow-md transition-shadow cursor-default max-w-md">
              <div className="w-10 h-10 rounded-xl bg-white flex items-center justify-center text-indigo-600 text-lg shadow-sm shrink-0 border border-slate-100">
                  ✨
              </div>
              <div>
                  <div className="text-[10px] font-bold text-indigo-500 uppercase tracking-widest mb-0.5">AI Coach Insight</div>
                  <div className="text-xs text-slate-600 font-medium leading-snug">
                      Great balance between {getLanguageName(userProfile.targetLanguages[0])} and {getLanguageName(userProfile.targetLanguages[1] || 'Review')} today.
                  </div>
              </div>
          </div>
      </div>

      {/* 1. Metrics Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
          {/* Total Hours with Polyglot Breakdown */}
          <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 hover:border-slate-200 transition-all flex flex-col justify-between h-36 relative overflow-hidden">
              <div className="flex justify-between items-start z-10">
                  <span className="text-slate-500 font-bold text-xs uppercase tracking-wider">Total Hours</span>
                  <span className="text-slate-300">⏱</span>
              </div>
              <div className="z-10">
                  <div className="flex items-baseline gap-1 mb-2">
                     <span className="text-4xl font-bold text-slate-900">{totalHours}</span>
                     <span className="text-sm font-medium text-slate-400">h</span>
                  </div>
                  {/* Visual Breakdown Bar */}
                  {totalHours > 0 && (
                      <div className="w-full h-2 rounded-full flex overflow-hidden bg-slate-100">
                          {sortedLanguages.map(([lang, mins]) => (
                              <div 
                                key={lang} 
                                className={`h-full ${lang === 'ja' ? 'bg-red-400' : lang === 'en' ? 'bg-blue-400' : 'bg-slate-400'}`} 
                                style={{ width: `${(Number(mins) / (totalHours * 60)) * 100}%` }}
                                title={`${getLanguageName(lang)}: ${Math.round(Number(mins)/60)}h`}
                              ></div>
                          ))}
                      </div>
                  )}
                  <div className="flex gap-3 mt-1.5">
                      {sortedLanguages.slice(0, 3).map(([lang, mins]) => (
                          <div key={lang} className="text-[10px] font-bold text-slate-500 flex items-center gap-1">
                              <span>{getLanguageFlag(lang)}</span>
                              <span>{Math.round(Number(mins)/60 * 10)/10}h</span>
                          </div>
                      ))}
                  </div>
              </div>
          </div>

          <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 hover:border-slate-200 transition-all flex flex-col justify-between h-36 relative overflow-hidden">
              <div className="flex justify-between items-start z-10">
                  <span className="text-slate-500 font-bold text-xs uppercase tracking-wider">Daily Plan</span>
                  <span className="text-slate-300">📅</span>
              </div>
              <div className="z-10 flex items-end justify-between">
                  <div className="flex items-baseline gap-1">
                      {todayPlan ? (
                          <>
                            <span className="text-4xl font-bold text-slate-900">{todayCompleted}</span>
                            <span className="text-xl font-bold text-slate-300">/</span>
                            <span className="text-xl font-bold text-slate-400">{todayTotal}</span>
                            <span className="text-xs font-medium text-slate-400 ml-1">tasks</span>
                          </>
                      ) : (
                          <span className="text-2xl font-bold text-slate-300">Not Started</span>
                      )}
                  </div>
                  {todayPlan ? (
                       <span className={`text-xs font-bold px-2 py-1 rounded-md border ${
                           todayCompleted === todayTotal && todayTotal > 0
                           ? 'text-green-600 bg-green-50 border-green-100'
                           : 'text-indigo-600 bg-indigo-50 border-indigo-100'
                       }`}>
                           {todayCompleted === todayTotal && todayTotal > 0 ? 'Done' : 'Active'}
                       </span>
                  ) : (
                      <span className="text-xs font-bold text-slate-400 bg-slate-50 px-2 py-1 rounded-md border border-slate-100">
                          Off
                      </span>
                  )}
              </div>
          </div>

          <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 hover:border-slate-200 transition-all flex flex-col justify-between h-36 relative overflow-hidden">
              <div className="flex justify-between items-start z-10">
                  <span className="text-slate-500 font-bold text-xs uppercase tracking-wider">Active Langs</span>
                  <span className="text-slate-300">🌐</span>
              </div>
              <div className="z-10 flex flex-col justify-end h-full">
                  <div className="flex gap-2">
                      {userProfile.targetLanguages.map(lang => (
                          <span key={lang} className="text-2xl bg-slate-50 border border-slate-100 rounded-lg p-1.5 shadow-sm" title={getLanguageName(lang)}>
                              {getLanguageFlag(lang)}
                          </span>
                      ))}
                  </div>
              </div>
          </div>

          <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 hover:border-slate-200 transition-all flex flex-col justify-between h-36 relative overflow-hidden">
              <div className="flex justify-between items-start z-10">
                  <span className="text-slate-500 font-bold text-xs uppercase tracking-wider">Streak</span>
                  <span className="text-slate-300">🔥</span>
              </div>
              <div className="z-10 flex items-end justify-between">
                  <div className="flex items-baseline gap-1">
                     <span className="text-4xl font-bold text-slate-900">{streak}</span>
                     <span className="text-sm font-medium text-slate-400">days</span>
                  </div>
                  <div className="flex gap-0.5 h-3 items-end">
                      {[1,2,3,4,5].map(i => (
                          <div key={i} className={`w-1 rounded-t-sm ${i <= streak ? 'bg-orange-400 h-full' : 'bg-slate-100 h-1/2'}`}></div>
                      ))}
                  </div>
              </div>
          </div>
      </div>

      {/* 2. Consistency Heatmap */}
      <ConsistencyHeatmap plans={plans} />

      {/* 3. Main Content Split */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

          {/* Col 1: Skill Matrix */}
