                  <span className="text-[10px] font-bold bg-slate-100 text-slate-500 px-2 py-1 rounded border border-slate-200">AGGREGATED</span>
              </div>

              <div className="flex-1 w-full flex items-center justify-center mt-8 mb-4">
                  <div className="w-[320px] h-[320px]">
                      <RadarChart stats={radarStats} />
                  </div>
              </div>

              <div className="w-full p-4 border-t border-slate-50 flex justify-between text-[10px] font-bold text-slate-400 uppercase tracking-wider bg-slate-50/30">
                  <span>Weakness: Speaking</span>
                  <span className="text-indigo-500 cursor-pointer hover:underline">View Report →</span>
              </div>
          </div>

          {/* Col 2: Resource Usage (Focus) */}
          <ResourceUsageList resources={resources} plans={plans} />

          {/* Col 3: Active Projects (Polyglot Visuals) */}
          <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col h-full min-h-[400px]">
              <div className="flex justify-between items-center mb-6">
                  <h3 className="font-bold text-slate-900">Active Missions</h3>
                  <button className="text-slate-400 hover:text-slate-600 text-xs font-bold uppercase tracking-wide">See All</button>
              </div>

              <div className="flex-1 space-y-4 overflow-y-auto custom-scrollbar">
                  {projects.filter(p => p.status === 'active').slice(0, 3).map((project, idx) => {
                      const style = getProjectStyle(project.language);
                      const progress = getProjectProgress(project);

                      return (
                          <div key={project.id} className={`group p-5 rounded-2xl border ${style.border} bg-white hover:shadow-md transition-all cursor-pointer`}>
                              <div className="flex items-center gap-4">
                                  {/* Flag + Icon Box */}
                                  <div className={`w-12 h-12 rounded-xl ${style.icon} flex items-center justify-center font-bold text-2xl shadow-sm shrink-0 relative overflow-hidden`}>
                                      <span className="z-10">{getLanguageFlag(project.language)}</span>
                                      <div className={`absolute bottom-0 left-0 right-0 h-1.5 ${style.bar} opacity-20`}></div>
                                  </div>

                                  {/* Info */}
                                  <div className="flex-1 min-w-0 py-1">
                                      <div className="flex justify-between items-center mb-1">
                                          <h4 className="font-bold text-slate-800 truncate text-sm">{project.title}</h4>
                                          <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded ${style.bg} ${style.text}`}>
                                              {getDaysDue(project.deadline)}
                                          </span>
                                      </div>

                                      {/* Progress Bar */}
                                      <div className="flex items-center gap-2">
                                          <div className="flex-1 h-1.5 bg-slate-100 rounded-full overflow-hidden">
                                              <div 
                                                  className={`h-full rounded-full ${style.bar}`} 
                                                  style={{ width: `${progress}%` }}
                                              ></div>
                                          </div>
                                          <span className="text-[10px] font-bold text-slate-400 w-6 text-right">{progress}%</span>
                                      </div>
                                  </div>
                              </div>
                          </div>
                      );
                  })}

                  {projects.filter(p => p.status === 'active').length === 0 && (
                      <div className="flex flex-col items-center justify-center h-full text-slate-400 bg-slate-50/50 rounded-2xl border border-dashed border-slate-200">
                          <span className="text-3xl mb-3 opacity-50">🚀</span>
                          <span className="text-sm font-medium">No active projects. Launch one now!</span>
                      </div>
                  )}
              </div>
          </div>
      </div>
    </div>
  );
};

