import React, { useState } from 'react';
import { UserProfile, SUPPORTED_LANGUAGES, CEFRLevel, CEFR_DESCRIPTIONS, LanguageCode } from '../types';

interface OnboardingProps {
  onComplete: (profile: UserProfile) => void;
}

const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [step, setStep] = useState<1 | 2 | 3>(1);
  const [nativeLanguage, setNativeLanguage] = useState<LanguageCode | null>(null);
  const [targetLanguages, setTargetLanguages] = useState<LanguageCode[]>([]);
  const [cefrLevel, setCefrLevel] = useState<CEFRLevel | null>(null);

  const handleNext = () => {
    if (step === 1 && nativeLanguage) setStep(2);
    else if (step === 2 && targetLanguages.length > 0) setStep(3);
    else if (step === 3 && cefrLevel) {
      // Initialize levels for all selected languages
      const initialLevels: Record<string, CEFRLevel> = {};
      targetLanguages.forEach(lang => {
          initialLevels[lang] = cefrLevel;
      });

      onComplete({
        nativeLanguage: nativeLanguage!,
        targetLanguages: targetLanguages,
        cefrLevel: cefrLevel,
        levels: initialLevels
      });
    }
  };

  const toggleTargetLanguage = (code: LanguageCode) => {
    if (targetLanguages.includes(code)) {
      setTargetLanguages(targetLanguages.filter(c => c !== code));
    } else {
      setTargetLanguages([...targetLanguages, code]);
    }
  };

  return (
    <div className="min-h-screen bg-slate-900 flex flex-col items-center justify-center p-6 font-inter">
      <div className="max-w-4xl w-full bg-white rounded-3xl shadow-2xl overflow-hidden flex flex-col md:flex-row min-h-[600px]">

        {/* Sidebar / Info Panel */}
        <div className="md:w-1/3 bg-gradient-to-br from-teal-600 to-indigo-700 p-10 flex flex-col text-white justify-between">
          <div>
            <h1 className="text-3xl font-bold mb-2">LangVault</h1>
            <p className="text-teal-100 text-sm tracking-wide uppercase">Your Private Language Asset Store</p>
          </div>

          <div className="space-y-8 my-8">
            <div className={`transition-opacity duration-300 ${step === 1 ? 'opacity-100' : 'opacity-40'}`}>
              <div className="flex items-center gap-3 mb-2">
                <span className="w-8 h-8 rounded-full bg-white/20 flex items-center justify-center text-sm font-bold">1</span>
                <h3 className="font-semibold text-lg">Mother Tongue</h3>
              </div>
              <p className="text-sm text-teal-100 pl-11">So we know how to translate for you.</p>
            </div>

            <div className={`transition-opacity duration-300 ${step === 2 ? 'opacity-100' : 'opacity-40'}`}>
              <div className="flex items-center gap-3 mb-2">
                 <span className="w-8 h-8 rounded-full bg-white/20 flex items-center justify-center text-sm font-bold">2</span>
                <h3 className="font-semibold text-lg">Target Language</h3>
              </div>
              <p className="text-sm text-teal-100 pl-11">Choose one or more languages to conquer.</p>
            </div>

            <div className={`transition-opacity duration-300 ${step === 3 ? 'opacity-100' : 'opacity-40'}`}>
              <div className="flex items-center gap-3 mb-2">
                 <span className="w-8 h-8 rounded-full bg-white/20 flex items-center justify-center text-sm font-bold">3</span>
                <h3 className="font-semibold text-lg">Current Level</h3>
              </div>
              <p className="text-sm text-teal-100 pl-11">Set your baseline to tailor the challenge.</p>
            </div>
          </div>

          <div className="text-xs text-teal-200">
            Low Pressure × High Challenge
          </div>
        </div>

        {/* Interaction Panel */}
        <div className="md:w-2/3 p-10 bg-slate-50 flex flex-col">
          <div className="flex-1">
            {step === 1 && (
              <div className="animate-in slide-in-from-right fade-in duration-300">
                <h2 className="text-2xl font-bold text-slate-800 mb-6">What is your native language?</h2>
                <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                  {SUPPORTED_LANGUAGES.map((lang) => (
                    <button
                      key={lang.code}
                      onClick={() => setNativeLanguage(lang.code)}
                      className={`p-4 rounded-xl border text-left flex items-center gap-3 transition-all ${
                        nativeLanguage === lang.code 
                          ? 'border-teal-500 bg-teal-50 ring-2 ring-teal-500 ring-offset-1' 
                          : 'border-slate-200 bg-white hover:border-teal-300 hover:shadow-sm'
                      }`}
                    >
                      <span className="text-2xl">{lang.flag}</span>
                      <div>
                        <div className="font-semibold text-slate-800">{lang.name}</div>
                        <div className="text-xs text-slate-400">{lang.nativeName}</div>
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            )}

            {step === 2 && (
              <div className="animate-in slide-in-from-right fade-in duration-300">
                <h2 className="text-2xl font-bold text-slate-800 mb-6">What do you want to learn?</h2>
                <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                  {SUPPORTED_LANGUAGES.map((lang) => (
                    <button
                      key={lang.code}
                      onClick={() => toggleTargetLanguage(lang.code)}
                      disabled={nativeLanguage === lang.code}
                      className={`p-4 rounded-xl border text-left flex items-center gap-3 transition-all ${
                        nativeLanguage === lang.code ? 'opacity-30 cursor-not-allowed bg-slate-100' :
                        targetLanguages.includes(lang.code)
                          ? 'border-indigo-500 bg-indigo-50 ring-2 ring-indigo-500 ring-offset-1' 
                          : 'border-slate-200 bg-white hover:border-indigo-300 hover:shadow-sm'
                      }`}
                    >
                      <span className="text-2xl">{lang.flag}</span>
                      <div>
                        <div className="font-semibold text-slate-800">{lang.name}</div>
                        <div className="text-xs text-slate-400">{lang.nativeName}</div>
                      </div>
                    </button>
                  ))}
                </div>
                {targetLanguages.length === 0 && (
                   <p className="text-slate-400 text-sm mt-4 text-center">Please select at least one language.</p>
                )}
              </div>
            )}

            {step === 3 && (
              <div className="animate-in slide-in-from-right fade-in duration-300">
                <h2 className="text-2xl font-bold text-slate-800 mb-6">What is your current level?</h2>
                <div className="space-y-3">
                   {(Object.keys(CEFR_DESCRIPTIONS) as CEFRLevel[]).map((level) => (
                     <button
                        key={level}
                        onClick={() => setCefrLevel(level)}
                        className={`w-full p-4 rounded-xl border text-left transition-all ${
                           cefrLevel === level
                             ? 'border-purple-500 bg-purple-50 ring-2 ring-purple-500'
                             : 'border-slate-200 bg-white hover:border-purple-300 hover:shadow-sm'
                        }`}
                     >
                        <div className="flex items-center gap-4">
                            <div className={`w-12 h-12 rounded-lg flex items-center justify-center font-bold text-xl ${
                                cefrLevel === level ? 'bg-purple-600 text-white' : 'bg-slate-100 text-slate-500'
                            }`}>
                                {level}
                            </div>
                            <div>
                                <div className="font-bold text-slate-800">
                                    {level === 'A1' || level === 'A2' ? 'Beginner' : 
                                     level === 'B1' || level === 'B2' ? 'Intermediate' : 'Advanced'}
                                </div>
                                <div className="text-sm text-slate-500">{CEFR_DESCRIPTIONS[level]}</div>
                            </div>
                        </div>
                     </button>
                   ))}
                </div>
              </div>
            )}
          </div>

          <div className="mt-8 flex justify-end">
             <button
                onClick={handleNext}
                disabled={
                    (step === 1 && !nativeLanguage) ||
                    (step === 2 && targetLanguages.length === 0) ||
                    (step === 3 && !cefrLevel)
                }
                className="bg-slate-900 text-white px-8 py-3 rounded-xl font-bold hover:bg-slate-800 disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-lg flex items-center gap-2"
             >
                {step === 3 ? 'Open Vault' : 'Next Step'}
                <span>→</span>
             </button>
          </div>
        </div>

      </div>
    </div>
  );
};

export default Onboarding;

import React, { useState, useRef, useEffect } from 'react';
import { marked } from 'marked';
import { sendChatMessage, transcribeAudio, generateFrictionSummary } from '../services/geminiService';
import { ChatMessage, DailyPlan, SUPPORTED_LANGUAGES } from '../types';

interface ChatCoachProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  plans?: Record<string, DailyPlan>;
  nativeLanguage?: string;
}

const ChatCoach: React.FC<ChatCoachProps> = ({ messages, setMessages, plans = {}, nativeLanguage = 'zh' }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [frictionSummary, setFrictionSummary] = useState<string | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  useEffect(() => scrollToBottom(), [messages]);

  const handleSend = async (overrideInput?: string) => {
    const textToSend = overrideInput || input;
    if (!textToSend.trim()) return;

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', text: textToSend, timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    try {
      // Use the updated messages list (including the one just added) for history
      const history = [...messages, userMsg].map(m => ({ 
          role: m.role, 
          parts: [{ text: m.text }] 
      }));

      const responseText = await sendChatMessage(history, userMsg.text);

      const botMsg: ChatMessage = { 
          id: (Date.now() + 1).toString(), 
          role: 'model', 
          text: responseText || "I didn't catch that.", 
          timestamp: Date.now() 
      };
      setMessages(prev => [...prev, botMsg]);
    } catch (error) { 
        console.error(error);
        const errorMsg: ChatMessage = { id: 'err', role: 'model', text: '抱歉，连接教练时出了点问题。请稍后再试。', timestamp: Date.now() };
        setMessages(prev => [...prev, errorMsg]);
    } finally { 
        setIsLoading(false); 
    }
  };

  const handleSummarizeToday = async () => {
    const today = new Date().toISOString().split('T')[0];
    const todayPlan = plans[today];

    if (!todayPlan || todayPlan.tasks.length === 0) {
        alert("今天还没有追踪到任何任务。快去计划你的第一项学习吧！");
        return;
    }

    setIsLoading(true);
    try {
        const langName = SUPPORTED_LANGUAGES.find(l => l.code === nativeLanguage)?.name || 'Chinese';
        const summary = await generateFrictionSummary(todayPlan.tasks, langName);
        setFrictionSummary(summary);

        // Add summary to chat directly
        const botMsg: ChatMessage = { 
            id: Date.now().toString(), 
            role: 'model', 
            text: `✨ **今日进度与难点分析 (Friction Analysis):**\n\n${summary}\n\n关于这些反馈，你想详细聊聊哪一部分？`, 
            timestamp: Date.now() 
        };
        setMessages(prev => [...prev, botMsg]);
    } catch (e) {
        console.error(e);
    } finally {
        setIsLoading(false);
    }
  };

  const handleRecord = async () => {
      if (isRecording) return; 
      setIsRecording(true);
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        const mediaRecorder = new MediaRecorder(stream);
        const chunks: Blob[] = [];
        mediaRecorder.ondataavailable = (e) => chunks.push(e.data);
        mediaRecorder.onstop = async () => {
            const blob = new Blob(chunks, { type: 'audio/webm' });
            const reader = new FileReader();
            reader.readAsDataURL(blob);
            reader.onloadend = async () => {
                const base64data = reader.result?.toString().split(',')[1];
                if (base64data) {
                    setIsLoading(true);
                    try {
                        const transcript = await transcribeAudio(base64data, blob.type);
                        setInput(transcript || "");
                    } catch (e) { console.error(e); } finally { setIsLoading(false); }
                }
            }
            stream.getTracks().forEach(t => t.stop());
        };
        mediaRecorder.start();
        setTimeout(() => { mediaRecorder.stop(); setIsRecording(false); }, 3000);
      } catch (e) { console.error(e); setIsRecording(false); }
  }

  // Helper to safely render markdown
  const renderMarkdown = (text: string) => {
    try {
      const html = marked.parse(text);
      return { __html: html };
    } catch (e) {
      return { __html: text };
    }
  };

  return (
    <div className="flex flex-col h-full bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
      <div className="flex items-center justify-between px-6 py-4 border-b border-slate-100 bg-slate-50">
           <div>
               <h3 className="font-bold text-slate-800 flex items-center gap-2">
                   💬 AI 教练 (LangVault Coach)
               </h3>
               <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">Persistent Memory Enabled</p>
           </div>
           <button 
             onClick={handleSummarizeToday} 
             disabled={isLoading}
             className="text-xs font-bold text-indigo-600 bg-white px-4 py-2 rounded-xl border border-indigo-100 hover:bg-indigo-50 hover:shadow-sm transition-all flex items-center gap-2"
           >
               ✨ 分析今日进度
           </button>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-[#F8FAFC] custom-scrollbar">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}>
            <div className={`max-w-[85%] rounded-2xl p-4 shadow-sm relative ${
                msg.role === 'user' 
                ? 'bg-indigo-600 text-white rounded-br-none' 
                : 'bg-white text-slate-700 border border-slate-200 rounded-bl-none'
            }`}>
              <div 
                className="markdown-content text-sm leading-relaxed"
                dangerouslySetInnerHTML={renderMarkdown(msg.text)}
              />
            </div>
          </div>
        ))}
        {isLoading && (
            <div className="flex justify-start">
                <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-200 flex space-x-2">
