// --- SVG Radar Chart Component ---
const RadarChart = ({ stats }: { stats: { label: string; value: number }[] }) => {
    const size = 400;
    const center = size / 2;
    const radius = 90; 
    const angleStep = (Math.PI * 2) / stats.length;
    const points = stats.map((stat, i) => {
      const angle = i * angleStep - Math.PI / 2;
      const value = Math.max(0, Math.min(stat.value, 100)) / 100; 
      const r = value * radius;
      return `${center + r * Math.cos(angle)},${center + r * Math.sin(angle)}`;
    }).join(' ');

    return (
      <svg width="100%" height="100%" viewBox={`0 0 ${size} ${size}`}>
        {[0.25, 0.5, 0.75, 1].map((scale, idx) => {
            const polyPoints = stats.map((_, i) => {
                const angle = i * angleStep - Math.PI / 2;
                const r = radius * scale;
                return `${center + r * Math.cos(angle)},${center + r * Math.sin(angle)}`;
            }).join(' ');
            return <polygon key={idx} points={polyPoints} fill="none" stroke="#E2E8F0" strokeWidth="1" />;
        })}
        {stats.map((stat, i) => {
             const angle = i * angleStep - Math.PI / 2;
             const x = center + radius * Math.cos(angle);
             const y = center + radius * Math.sin(angle);
             return (
                <g key={i}>
                    <line x1={center} y1={center} x2={x} y2={y} stroke="#F1F5F9" strokeWidth="1" />
                    <text x={center + (radius + 35) * Math.cos(angle)} y={center + (radius + 35) * Math.sin(angle)} textAnchor="middle" dominantBaseline="middle" className="text-[12px] font-bold fill-slate-500 uppercase tracking-widest">{stat.label}</text>
                </g>
             );
        })}
        <polygon points={points} fill="rgba(99, 102, 241, 0.15)" stroke="#6366f1" strokeWidth="2" strokeLinejoin="round" />
        {points.split(' ').map((p, i) => {
            const [cx, cy] = p.split(',');
            return <circle key={i} cx={cx} cy={cy} r="4" fill="#6366f1" stroke="white" strokeWidth="2" />;
        })}
      </svg>
    );
};

// --- Resource Usage List Component ---
const ResourceUsageList = ({ resources, plans }: { resources: Resource[], plans: Record<string, DailyPlan> }) => {
    const usageMap = useMemo(() => {
        const map: Record<string, number> = {};
        Object.values(plans).forEach(plan => {
            plan.tasks.forEach(task => { if (task.completed && task.resourceId) map[task.resourceId] = (map[task.resourceId] || 0) + 1; });
        });
        return map;
    }, [plans]);

    const focusResources = resources.filter(r => r.isDailyFocus || r.status === 'in-progress');
    const sortedFocus = [...focusResources].sort((a, b) => (usageMap[b.id] || 0) - (usageMap[a.id] || 0));
    const maxVal = Math.max(...(Object.values(usageMap) as number[]), 5); 

    return (
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col h-full min-h-[400px]">
            <div className="flex justify-between items-center mb-6">
                <h3 className="font-bold text-slate-900">Focus Resources</h3>
                <span className="text-[10px] font-bold bg-amber-50 text-amber-600 px-2 py-1 rounded border border-amber-100">ON DECK</span>
            </div>
            <div className="flex-1 space-y-5 overflow-y-auto custom-scrollbar">
                {sortedFocus.map(res => {
                    const count = usageMap[res.id] || 0;
                    const percent = Math.min(100, (count / maxVal) * 100);
                    return (
                        <div key={res.id} className="group">
                            <div className="flex justify-between text-xs font-bold text-slate-700 mb-2">
                                <span className="truncate pr-2 flex items-center gap-2"><span className="text-base">{getLanguageFlag(res.language)}</span>{res.title}</span>
                                <span className="text-slate-400">{count} sessions</span>
                            </div>
                            <div className="w-full bg-slate-100 rounded-full h-2.5 overflow-hidden">
                                <div className={`h-full rounded-full transition-all duration-1000 ${res.language === 'ja' ? 'bg-red-400' : 'bg-blue-400'}`} style={{ width: `${Math.max(5, percent)}%` }} ></div>
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
    )
}

const Dashboard: React.FC<DashboardProps> = ({ plans = {}, projects = [], resources = [], areas = [], userProfile, flashcards = [] }) => {
  const allCompletedTasks = useMemo(() => {
    const tasks: Task[] = [];
    Object.values(plans || {}).forEach(plan => { plan?.tasks?.forEach(task => { if (task.completed) tasks.push(task); }); });
    return tasks;
  }, [plans]);

  const totalHours = Math.round(allCompletedTasks.reduce((acc: number, t) => acc + (Number(t.durationMinutes) || 0), 0) / 60); 

  const streak = useMemo(() => {
    const activeDates = Object.values(plans).filter(plan => plan.tasks.some(t => t.completed)).map(plan => plan.date).sort();
    if (activeDates.length === 0) return 0;
    const getISO = (d: Date) => d.toISOString().split('T')[0];
    const today = new Date();
    const yesterday = new Date(); yesterday.setDate(yesterday.getDate() - 1);
    if (!activeDates.includes(getISO(today)) && !activeDates.includes(getISO(yesterday))) return 0;
    let currentStreak = 0;
    let checkDate = activeDates.includes(getISO(today)) ? today : yesterday;
    while (activeDates.includes(getISO(checkDate))) { currentStreak++; checkDate.setDate(checkDate.getDate() - 1); }
    return currentStreak;
  }, [plans]);

  const radarStats = useMemo(() => {
      const areaMap: Record<string, number> = { 'READING': 30, 'WRITING': 30, 'LISTENING': 30, 'SPEAKING': 30 };
      allCompletedTasks.forEach(t => {
          let type = 'READING';
          if (t.type?.toLowerCase().includes('listen')) type = 'LISTENING';
          else if (t.type?.toLowerCase().includes('speak')) type = 'SPEAKING';
          else if (t.type?.toLowerCase().includes('writ')) type = 'WRITING';
          areaMap[type] = Math.min(100, (areaMap[type] || 30) + 5);
      });
      return Object.entries(areaMap).map(([label, value]) => ({ label, value }));
  }, [allCompletedTasks]);

  const todayStr = new Date().toISOString().split('T')[0];
  const todayPlan = plans[todayStr];

  return (
    <div className="space-y-6 font-inter text-slate-800 animate-in fade-in duration-500 pb-10">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6 mb-2">
          <div>
              <h1 className="text-3xl font-bold text-slate-900 mb-1">Good Morning, {userProfile.name?.split(' ')[0] || 'Learner'}</h1>
              <p className="text-slate-500 font-medium">Your {userProfile.targetLanguages.length > 1 ? 'polyglot' : 'fluency'} engine is running smooth.</p>
          </div>
          <div className="bg-slate-50 border border-slate-200 px-4 py-3 rounded-2xl flex items-center gap-4 shadow-sm max-w-md">
              <div className="w-10 h-10 rounded-xl bg-white flex items-center justify-center text-indigo-600 text-lg shadow-sm border border-slate-100">✨</div>
              <div>
                  <div className="text-[10px] font-bold text-indigo-500 uppercase tracking-widest mb-0.5">Startup Growth Insight</div>
                  <div className="text-xs text-slate-600 font-medium leading-snug">Focus on M2 Habit systems to double retention this month.</div>
              </div>
          </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
          <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 h-36 flex flex-col justify-between">
              <span className="text-slate-500 font-bold text-xs uppercase tracking-wider">Total Hours</span>
              <div className="flex items-baseline gap-1"><span className="text-4xl font-bold text-slate-900">{totalHours}</span><span className="text-sm font-medium text-slate-400">h</span></div>
          </div>
          <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 h-36 flex flex-col justify-between">
              <span className="text-slate-500 font-bold text-xs uppercase tracking-wider">Daily Plan</span>
              <div className="flex items-baseline gap-1">
                <span className="text-4xl font-bold text-slate-900">{todayPlan?.tasks?.filter(t => t.completed).length || 0}</span>
                <span className="text-xl font-bold text-slate-300">/</span>
                <span className="text-xl font-bold text-slate-400">{todayPlan?.tasks?.length || 0}</span>
              </div>
          </div>
          <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 h-36 flex flex-col justify-between">
              <span className="text-slate-500 font-bold text-xs uppercase tracking-wider">Active Langs</span>
              <div className="flex gap-2">{userProfile.targetLanguages.map(lang => <span key={lang} className="text-2xl bg-slate-50 border border-slate-100 rounded-lg p-1.5 shadow-sm">{getLanguageFlag(lang)}</span>)}</div>
          </div>
          <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 h-36 flex flex-col justify-between">
              <span className="text-slate-500 font-bold text-xs uppercase tracking-wider">Streak</span>
              <div className="flex items-baseline gap-1"><span className="text-4xl font-bold text-slate-900">{streak}</span><span className="text-sm font-medium text-slate-400">days</span></div>
          </div>
      </div>

      <ConsistencyHeatmap plans={plans} />

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col items-center min-h-[400px]">
              <h3 className="w-full font-bold text-slate-900 mb-6">Meta Skills</h3>
              <div className="flex-1 w-full"><RadarChart stats={radarStats} /></div>
          </div>
          <ResourceUsageList resources={resources} plans={plans} />
          <MissionRoadmap />
      </div>
    </div>
  );
};

